fixtures.template:
{# A game that keeps Twig thin and has both playthrough hooks. #}
<div
    class="rfx-game"
    x-data='{ plays: {{ plays|json }}, revealed: [], files: {{ files|json }} }'
    style="background: {{ settings.background }}; color: {{ settings['button_text_color'] }}"
>
    {% if play_count == 0 %}
        <p>Buy tickets to play.</p>
    {% elseif plays %}
        <button type="button" data-rafflex-play @click="revealed.push(plays[revealed.length])">Play</button>
    {% else %}
        <p>Nothing to play.</p>
    {% endif %}
    <img src="{{ files['background'] }}" alt="" />
    <audio src="{{ files.win_jingle }}"></audio>
    <template x-for="play in revealed">
        <p :data-rafflex-result="play.won ? 'win' : 'lose'" x-text="play.won ? 'Win' : 'No win'"></p>
    </template>
    {%- if settings.show_footer -%}
        <footer>{{ tenant.name|json }}</footer>
    {%- endif -%}
</div>

{% set heading = options.heading|default('Ending soon') %}
<section>
    <h2>{{ heading|upper }}</h2>
    {% for competition in competitions.ending_soon|slice(0, 3) %}
        <a href="{{ competition.url }}">{{ competition.title }}</a>
    {% endfor %}
</section>
